config.script:
# Set 6-month trend window
self.custom.trendEndDate   = system.date.now()
self.custom.trendStartDate = system.date.addMonths(self.custom.trendEndDate, -6)
self.custom.selectedEquipment = 'all'
self.custom.comparisonSiteId  = 0

# Pre-populate actuals from last recorded entry
try:
	prevDs = system.db.runNamedQuery(
		"coolingTowerData/getLastActualsBySite",
		{"siteId": self.params.siteId}
	)
	prev = {}
	for r in range(prevDs.getRowCount()):
		eqId    = str(prevDs.getValueAt(r, 'coolingTowerDataID'))
		paramId = str(prevDs.getValueAt(r, 'parameterTypesID'))
		val     = prevDs.getValueAt(r, 'value')
		if eqId not in prev: prev[eqId] = {}
		prev[eqId][paramId] = val
	self.custom.previousActuals = prev
except Exception as e:
	system.perspective.print('Pre-populate error: ' + str(e))

