# Build dropdown options from enabled equipment for this site
options = [{'label': 'All Equipment', 'value': 'all'}]
if value is not None:
	ds = system.dataset.toPyDataSet(value)
	for row in ds:
		options.append({
			'label': row['Parameter'],
			'value': str(row['id'])
		})
return options

if value is not None and value.getRowCount() > 0:
	v = value.getValueAt(0, 'lastEntry')
	if v is not None:
		return 'Last entry: ' + system.date.format(v, 'MM/dd/yyyy')
return 'No data recorded'

if value is None:
	return 0
worst = 0
for r in range(value.getRowCount()):
	dev = value.getValueAt(r, 'deviation')
	if dev is not None:
		absDev = abs(dev)
		if absDev > worst:
			worst = absDev
return worst

if value is None: return {}
ds = system.dataset.toPyDataSet(value)
return {str(row['month']): row['baselineDAT'] for row in ds}

if value is None: return {}
result = {}
for r in range(value.getRowCount()):
	eqId    = str(value.getValueAt(r, 'coolingTowerDataID'))
	paramId = str(value.getValueAt(r, 'parameterTypesID'))
	val     = value.getValueAt(r, 'value')
	if eqId not in result:
		result[eqId] = {}
	result[eqId][paramId] = val
return result

if value is None: return system.dataset.toDataSet([], [])
try:
	selected = self.view.custom.selectedEquipment
except:
	selected = 'all'
pen_names = ['IWT Actual','POGT Actual','DAT Actual','IWT Target','POGT Target','DAT Target']
time_data = {}
count_data = {}
for r in range(value.getRowCount()):
	ts    = value.getValueAt(r, 't_stamp')
	eq_id = str(value.getValueAt(r, 'coolingTowerDataID') or '')
	pl    = str(value.getValueAt(r, 'paramLabel') or '')
	v     = value.getValueAt(r, 'value')
	if selected != 'all' and eq_id != str(selected): continue
	if pl not in pen_names: continue
	if ts not in time_data:
		time_data[ts] = {}
		count_data[ts] = {}
	if v is not None:
		if pl in time_data[ts] and time_data[ts][pl] is not None:
			time_data[ts][pl] = (time_data[ts][pl] * count_data[ts].get(pl,1) + v) / (count_data[ts].get(pl,1) + 1)
			count_data[ts][pl] = count_data[ts].get(pl,1) + 1
		else:
			time_data[ts][pl] = v
			count_data[ts][pl] = 1
headers = ['t_stamp'] + pen_names
rows = [[ts] + [time_data[ts].get(p) for p in pen_names] for ts in sorted(time_data.keys())]
return system.dataset.toDataSet(headers, rows)

config.script:
now = self.getSibling("DateTimeInput").props.value

if now is None:
	system.perspective.openPopup('saveValidation','Framework/ErrorPopup',
		params={'message': 'Please select a date before saving.'})
	return

# Get username for audit trail
try:
	submittedBy = self.session.props.auth.user.userName or 'unknown'
except:
	submittedBy = 'unknown'

rows = []
tabs      = ["MAC_BAC", "RNC_FNC", "GAN_GOX", "CDA_MISC"]
repeaters = ["FlexRepeater", "FlexRepeater_0"]
paramIds_to_save = ["6","3","1","4","2","5"]
paramId_map = {
	"6": "designApproachTempF",
	"3": "designApproachTempFTarget",
	"1": "designIncomingWaterTempF",
	"4": "designIncomingWaterTempFTarget",
	"2": "processGasOutTempF",
	"5": "processGasOutTempFTarget"
}
actuals = {"1", "2", "6"}

for tabName in tabs:
	try:
		tabView = self.getChild(tabName)
	except:
		continue
	for repeaterName in repeaters:
		try:
			repeater = tabView.getChild(repeaterName)
		except:
			continue
		for inst in repeater.props.instances:
			dataID = inst["params"].get("id")
			if dataID is None: continue
			for paramId in paramIds_to_save:
				paramName = paramId_map.get(paramId)
				value     = inst["params"].get(paramName)
				if paramId in actuals and (value is None or value == ''): continue
				rows.append({
					"coolingTowerDataID": dataID,
					"parameterTypesID":   paramId,
					"t_stamp":            now,
					"value":              value,
					"submittedBy":        submittedBy
				})

if not rows:
	system.perspective.openPopup('saveValidation','Framework/ErrorPopup',
		params={'message': 'No data to save. Enter at least one actual value.'})
	return

try:
	system.db.runNamedQuery(
		"coolingTowerData/insertCoolingTowerData",
		{"rows": rows, "submittedBy": submittedBy}
	)
	# Save notes if entered
	noteText = self.view.custom.notesText.strip()
	if noteText:
		system.db.runNamedQuery(
			"coolingTowerData/insertNote",
			{
				"siteId":      self.view.params.siteId,
				"t_stamp":     now,
				"note":        noteText,
				"submittedBy": submittedBy
			}
		)
		self.view.custom.notesText = ''
	system.perspective.openPopup('saveSuccess','Framework/SuccessPopup',
		params={'message': str(len(rows)) + ' records saved by ' + submittedBy + '.'})
except Exception as e:
	system.perspective.openPopup('saveError','Framework/ErrorPopup',
		params={'message': 'Save failed: ' + str(e)})

