self.view.custom.trendEndDate   = end
self.view.custom.trendStartDate = system.date.addMonths(end, -3)

end = system.date.now()
self.view.custom.trendEndDate   = end
self.view.custom.trendStartDate = system.date.addMonths(end, -6)

end = system.date.now()
self.view.custom.trendEndDate   = end
self.view.custom.trendStartDate = system.date.addMonths(end, -12)

try:
	ds = system.db.runNamedQuery(
		'coolingTowerData/getHistoryBySite',
		{
			'siteId':    self.view.params.siteId,
			'startDate': self.view.custom.trendStartDate,
			'endDate':   self.view.custom.trendEndDate
		}
	)
	siteName = str(self.view.custom.site or 'Site_' + str(self.view.params.siteId))
	fileName = siteName.replace(' ', '_') + '_trend_data.csv'
	csvBytes = system.dataset.toCSV(ds, True).encode('utf-8')
	system.perspective.download(fileName, csvBytes)
except Exception as e:
	system.perspective.openPopup(
		'exportError', 'Framework/ErrorPopup',
		params={'message': 'Export failed: ' + str(e)}
	)

siteId = self.view.params.siteId
monthMap = {
	1: self.getSibling('InputJan').props.value,
	2: self.getSibling('InputFeb').props.value,
	3: self.getSibling('InputMar').props.value,
	4: self.getSibling('InputApr').props.value,
	5: self.getSibling('InputMay').props.value,
	6: self.getSibling('InputJun').props.value,
	7: self.getSibling('InputJul').props.value,
	8: self.getSibling('InputAug').props.value,
	9: self.getSibling('InputSep').props.value,
	10: self.getSibling('InputOct').props.value,
	11: self.getSibling('InputNov').props.value,
	12: self.getSibling('InputDec').props.value
}
saved = 0
try:
	for month, val in monthMap.items():
		if val is not None:
			system.db.runNamedQuery(
				'coolingTowerData/upsertSeasonalBaseline',
				{'siteId': siteId, 'month': month, 'baselineDAT': float(val)}
			)
			saved += 1
	if saved > 0:
		system.perspective.openPopup('baselineOK', 'Framework/SuccessPopup',
			params={'message': str(saved) + ' month(s) saved successfully.'})
	else:
		system.perspective.openPopup('baselineErr', 'Framework/ErrorPopup',
			params={'message': 'No values entered. Enter at least one month.'})
except Exception as e:
	system.perspective.openPopup('baselineErr', 'Framework/ErrorPopup',
		params={'message': 'Save failed: ' + str(e)})
